# Whole directories (VM images, container storage, etc.)
IgnorePath '/var/lib/libvirt/images/*'

# Journal logs: rotated and regenerated, not configuration
IgnorePath '/var/log/journal/*'

# Coredumps
IgnorePath '/var/lib/systemd/coredump/*'

# Bootloader and kernel images (rebuilt by pacman)
IgnorePath '/boot/efi/EFI/Arch/*'

# Individual files
IgnorePath '/usr/lib/udev/hwdb.bin'

# Android studio
IgnorePath '/opt/android-studio/'

# Pattern covering the gnupg sockets and mirrorlist thats generated by reflector
IgnorePath '/etc/pacman.d/gnupg/S.*'
IgnorePath '/etc/pacman.d/mirrorlist'

# Pacman's per-package database (regenerated from packages)
IgnorePath '/var/lib/pacman/local/*'

# Everyday user directories
IgnorePath '/home/chilly/Downloads/'
IgnorePath '/home/chilly/Documents/'
IgnorePath '/home/chilly/dots/'
IgnorePath '/home/chilly/Games/'
IgnorePath '/home/chilly/Pictures/'
IgnorePath '/home/chilly/Codes/'

## Secrets (never track)
IgnorePath '/etc/shadow*'
IgnorePath '/etc/gshadow*'
IgnorePath '/etc/NetworkManager/system-connections/*'
IgnorePath '/var/lib/NetworkManager/secret_key'
IgnorePath '/etc/ssh/ssh_host_*'
IgnorePath '/etc/pacman.d/gnupg/*'
IgnorePath '/etc/playit/*'
IgnorePath '/etc/tenable_tag'
IgnorePath '/var/lib/dkms/mok.key'
IgnorePath '/var/lib/systemd/credential.secret'
IgnorePath '/var/lib/bluetooth/*'
IgnorePath '/var/lib/radarr/*'
IgnorePath '/etc/radarr/*'
IgnorePath '/var/db/sudo/*'

## Machine-specific identity and runtime state
IgnorePath '/etc/machine-id'
IgnorePath '/var/lib/dbus/machine-id'
IgnorePath '/etc/resolv.conf'
IgnorePath '/etc/.updated'
IgnorePath '/var/.updated'
IgnorePath '/etc/.pwd.lock'
IgnorePath '/var/tmp/*'
IgnorePath '/var/lib/NetworkManager/*'
IgnorePath '/var/lib/upower/*'
IgnorePath '/var/lib/systemd/random-seed'
IgnorePath '/var/lib/systemd/rfkill/*'
IgnorePath '/var/lib/systemd/timers/*'
IgnorePath '/var/lib/systemd/timesync/*'
IgnorePath '/var/lib/systemd/coredump/*'
IgnorePath '/var/lib/logrotate.status'
IgnorePath '/var/lib/lastlog/*'

## Logs (not configuration)
IgnorePath '/var/log/*'

## Large data and VM images
IgnorePath '/var/lib/libvirt/*'
IgnorePath '/var/lib/comfyui/*'
IgnorePath '/opt/comfyui/venv/*'

## Caches regenerated by package hooks
IgnorePath '/etc/ca-certificates/*'
IgnorePath '/etc/ssl/certs/*'
IgnorePath '/etc/fonts/conf.d/*'
IgnorePath '/etc/ld.so.cache'
IgnorePath '/usr/share/mime/*'
IgnorePath '/usr/share/icons/*/icon-theme.cache'
IgnorePath '/usr/share/glib-2.0/schemas/gschemas.compiled'
IgnorePath '/usr/lib/gio/modules/giomodule.cache'
IgnorePath '/usr/lib/gtk-*/*/immodules.cache'
IgnorePath '/usr/lib/gconv/gconv-modules.cache'
IgnorePath '/usr/lib/locale/locale-archive'
IgnorePath '/usr/lib/vlc/plugins/plugins.dat'
IgnorePath '/usr/share/info/dir'
IgnorePath '/var/lib/systemd/catalog/*'
IgnorePath '/var/lib/pacman/sync/*'
IgnorePath '/usr/lib/modules/*'

## Windows dual-boot and EFI files that pacman/Windows manage
IgnorePath '/boot/efi/EFI/Microsoft/*'
IgnorePath '/boot/efi/EFI/Boot/*'
IgnorePath '/boot/efi/System Volume Information/*'
IgnorePath '/boot/efi/EFI/amd-ucode.img'

## Leftover and backup files
IgnorePath '/etc/*.pacnew'
IgnorePath '/etc/*/*.pacnew'
IgnorePath '/etc/*/*/*.pacnew'
IgnorePath '/etc/ufw/*.202*'

## Sockets and per-package noise
IgnorePath '/etc/pacman.d/gnupg/S.*'
IgnorePath '/usr/lib/node_modules/typescript/*'

